<form class="filters card" method="get"><input type="hidden" name="page" value="schedule"><label>Lekce<select name="lesson"><option value="0">Všechny lekce</option><?php foreach(all('SELECT id,name FROM lessons ORDER BY name') as $l): ?><option value="<?=$l['id']?>" <?=$lesson===$l['id']?'selected':''?>><?=e($l['name'])?></option><?php endforeach ?></select></label><label>Trenér<select name="trainer"><option value="0">Všichni trenéři</option><?php foreach(all('SELECT id,name FROM trainers ORDER BY name') as $t): ?><option value="<?=$t['id']?>" <?=$trainer===$t['id']?'selected':''?>><?=e($t['name'])?></option><?php endforeach ?></select></label><?php field('date','Den','date',$date,false) ?><button>Zobrazit</button><a href="index.php?page=schedule" class="text-link">Zrušit filtr</a></form>
