<?php if($page!=='login'): ?><small class="muted">Zvolte unikátní heslo dlouhé alespoň 10 znaků (nejvýše 72 bajtů).</small><?php endif ?><button><?=$install?'Vytvořit správce':($register?'Vytvořit účet':'Přihlásit se')?></button></form>
